/**
 * A tiny method+path router over the store. Transport-agnostic on purpose —
 * `dispatch` takes strings and returns a plain object, so it is testable
 * without binding a socket.
 */

import type { Clock } from "./clock.ts";
import type { Config } from "./config.ts";
import { IngestQueue, parseSample } from "./ingest.ts";
import { rollup } from "./rollup.ts";
import { MemoryStore } from "./store.ts";
import { formatSummary, summarize } from "./summary.ts";
import { ValidationError } from "./validate.ts";

export interface Reply {
  status: number;
  body: string;
}

export class Router {
  private readonly store: MemoryStore;
  private readonly queue: IngestQueue;
  private readonly config: Config;
  private readonly clock: Clock;

  constructor(
    store: MemoryStore,
    queue: IngestQueue,
    config: Config,
    clock: Clock,
  ) {
    this.store = store;
    this.queue = queue;
    this.config = config;
    this.clock = clock;
  }

  dispatch(method: string, path: string, body = ""): Reply {
    if (method === "POST" && path === "/samples") {
      return this.ingest(body);
    }
    if (method === "GET" && path === "/series") {
      return { status: 200, body: this.store.series().join("\n") };
    }
    if (method === "GET" && path.startsWith("/summary/")) {
      return this.summary(path.slice("/summary/".length));
    }
    return { status: 404, body: `no route for ${method} ${path}` };
  }

  private ingest(body: string): Reply {
    const lines = body.split("\n").filter((line) => line.trim() !== "");
    let accepted = 0;
    try {
      for (const line of lines) {
        // Buffered, not stored: the queue is what absorbs a burst, and `tick()`
        // is what moves a sample into the store. A write that went straight to
        // the store would make the queue's overflow policy unreachable.
        this.queue.push(parseSample(line, this.clock.now()));
        accepted += 1;
      }
    } catch (error) {
      if (error instanceof ValidationError) {
        return { status: 400, body: `${error.message} (accepted ${accepted})` };
      }
      throw error;
    }
    return { status: 202, body: `accepted ${accepted}` };
  }

  private summary(series: string): Reply {
    const windows = rollup(
      this.store,
      series,
      this.config.windowMs,
      this.clock.now(),
      this.config.retentionMs,
    );
    return { status: 200, body: formatSummary(summarize(windows, series)) };
  }
}

export function createRouter(
  store: MemoryStore,
  queue: IngestQueue,
  config: Config,
  clock: Clock,
): Router {
  return new Router(store, queue, config, clock);
}
---index---
/**
 * Wiring. Everything above is injectable; this is the one place that decides
 * which real implementations get used.
 */

import type { Clock } from "./clock.ts";
import { SystemClock } from "./clock.ts";
import type { Config } from "./config.ts";
import { loadConfig } from "./config.ts";
import { IngestQueue } from "./ingest.ts";
import { MemoryStore } from "./store.ts";
import type { Router } from "./router.ts";
import { createRouter } from "./router.ts";

export interface Service {
  config: Config;
  store: MemoryStore;
  queue: IngestQueue;
  router: Router;
  /** Move queued samples into the store and expire anything past retention. */
  tick(): void;
}

export function createService(
  config: Config = loadConfig(),
  clock: Clock = new SystemClock(),
): Service {
  const store = new MemoryStore(config.maxSamples);
  const queue = new IngestQueue(config.maxSamples);
  const router = createRouter(store, queue, config, clock);

  return {
    config,
    store,
    queue,
    router,
    tick(): void {
      for (const sample of queue.drain()) store.put(sample);
      store.prune(clock.now() - config.retentionMs);
    },
  };
}

export function main(): void {
  const service = createService();
  // Drain whatever the queue holds and expire anything past retention before
  // reporting: the numbers below are about the store, and the store is only
  // current once the queue has been moved into it.
  service.tick();
  const series = service.store.series();
  process.stdout.write(
    `rollup service ready — window ${service.config.windowMs}ms, ` +
      `${series.length} series, ${service.queue.droppedCount()} dropped\n`,
  );
}

if (process.argv[1] && process.argv[1].endsWith("index.ts")) {
  main();
}

